 CREATE OR REPLACE FUNCTION public.insert_team_data_new(proletypecode character varying, roletypename character varying, shortname character varying, securityusersid uuid, roletypecodexx character varying, teamname character varying, teamtypecode character varying)          
  RETURNS text                                                                                                                                                                                                                                                                     
  LANGUAGE plpgsql                                                                                                                                                                                                                                                                 
 AS $function$                                                                                                                                                                                                                                                                     
 DECLARE                                                                                                                                                                                                                                                                           
  l_roleid int;                                                                                                                                                                                                                                                                    
  l_teamtypeid int;                                                                                                                                                                                                                                                                
  l_teamid uuid;                                                                                                                                                                                                                                                                   
  l_teammemberid uuid;                                                                                                                                                                                                                                                             
  l_teammemberroletypeid int;                                                                                                                                                                                                                                                      
  l_count int;                                                                                                                                                                                                                                                                     
 begin                                                                                                                                                                                                                                                                             
 select count(*) into l_count from public.roletype rt where rt.roletypecode =proletypecode;                                                                                                                                                                                        
 if(l_count=0) then                                                                                                                                                                                                                                                                
 INSERT INTO public.roletype                                                                                                                                                                                                                                                       
 ( roletypecode, roletypename, shortname, activeflag, effectivedate, expirationdate, insertedby, updatedby, insertedon, updatedon, old_id)                                                                                                                                         
 VALUES( proletypecode, roletypename, shortname, 1, now(), NULL, 'admin', 'admin', now(), now(), NULL);                                                                                                                                                                            
 end if;                                                                                                                                                                                                                                                                           
 --teamtype                                                                                                                                                                                                                                                                        
 select count(*) into l_count from public.teamtype where teamtypekey =teamtypecode;                                                                                                                                                                                                
 if(l_count=0) then                                                                                                                                                                                                                                                                
 select max(sequencenumber)+1 into l_teamtypeid from public.teamtype;                                                                                                                                                                                                              
 INSERT INTO public.teamtype                                                                                                                                                                                                                                                       
 (sequencenumber, teamtypekey, activeflag, description, insertedby, insertedon, updatedby, updatedon, effectivedate, expirationdate, "timestamp", old_id)                                                                                                                          
 VALUES(l_teamtypeid, teamtypecode, 1, teamtypecode, 'admin', now(), 'admin', now(), now(), NULL, NULL, NULL);                                                                                                                                                                     
                                                                                                                                                                                                                                                                                   
 --typesagencymapping                                                                                                                                                                                                                                                              
 INSERT INTO public.typesagencymapping                                                                                                                                                                                                                                             
 ( objecttypekey, teamtypekey, objecttype, activeflag, updatedby, updatedon, insertedby, insertedon, effectivedate, expirationdate)                                                                                                                                                
 VALUES( 'N', teamtypecode, 'ethnicgrouptype', 1, NULL, now(), 'admin', now(), now(), NULL);                                                                                                                                                                                       
                                                                                                                                                                                                                                                                                   
 --agencyconfig                                                                                                                                                                                                                                                                    
 INSERT INTO public.agencyconfig                                                                                                                                                                                                                                                   
 ( teamtypekey, ismanualrouting, activeflag, effectivedate, expirationdate, insertedby, updatedby, insertedon, updatedon, old_id)                                                                                                                                                  
 VALUES( teamtypecode, true, 1, now(), NULL, 'admin', 'admin', NULL, NULL, NULL);                                                                                                                                                                                                  
                                                                                                                                                                                                                                                                                   
 select gen_random_uuid() into l_teamid;                                                                                                                                                                                                                                           
 --team (parent)                                                                                                                                                                                                                                                                   
 INSERT INTO public.team                                                                                                                                                                                                                                                           
 (teamid,activeflag, teamname, teamnumber, teamtypekey, description, officetimingfrom, officetimingto, parentteamid, insertedby, insertedon, updatedby, updatedon, effectivedate, expirationdate, "timestamp", region, regionid, old_id, countyid)                                 
 VALUES(l_teamid, 1, teamName, teamtypecode, teamtypecode, teamtypecode, '08:00:00', '16:00:00', NULL, 'system', now(), 'system', now(), now(), now(), NULL, 1, null, NULL, NULL);                                                                                                 
                                                                                                                                                                                                                                                                                   
                                                                                                                                                                                                                                                                                   
 end if;                                                                                                                                                                                                                                                                           
 select max(sequencenumber)+1 into l_teammemberroletypeid from public.teammemberroletype;                                                                                                                                                                                          
 INSERT INTO public.teammemberroletype                                                                                                                                                                                                                                             
 (sequencenumber, roletypekey, activeflag, description, teamtypekey, isroutable, insertedby, insertedon, updatedby, updatedon, effectivedate, expirationdate, "timestamp", isupervisor, old_id)                                                                                    
 VALUES(l_teammemberroletypeid, roletypecodeXX, 1, teamtypecode, roletypecodeXX, true, 'system', now(), 'system', now(), now(), NULL, NULL, false, NULL);                                                                                                                          
                                                                                                                                                                                                                                                                                   
 select teamid into l_teamid from public.team where teamtypekey =teamtypecode;                                                                                                                                                                                                     
 select gen_random_uuid() into l_teammemberid;                                                                                                                                                                                                                                     
 INSERT INTO public.teammember                                                                                                                                                                                                                                                     
 ( teammemberid,activeflag, teamid, loadnumber, roletypekey, positioncode, description, isoncall, insertedby, insertedon, updatedby, updatedon, effectivedate, expirationdate, "timestamp", linenumber, voidedby, voidedon, voidreasonid, rtfdate, coadate, old_id, isdefaultroute)
 VALUES( l_teammemberid,1, l_teamid, '400202', proletypecode, '400202', NULL, NULL, 'system', now(), 'system', now(), now(), now(), NULL, NULL, NULL, NULL, NULL, now(), now(), NULL, NULL);                                                                                       
                                                                                                                                                                                                                                                                                   
                                                                                                                                                                                                                                                                                   
 INSERT INTO public.teammemberassignment                                                                                                                                                                                                                                           
 ( activeflag, teammemberid, securityusersid, insertedby, insertedon, updatedby, updatedon, effectivedate, expirationdate, "timestamp", voidedby, voidedon, voidreasonid, coadate, rtfdate, intakenumber, old_id)                                                                  
 VALUES( 1, l_teammemberid, securityusersid, 'admin', '2018-12-21 09:33:07.747', 'admin',  now(),  now(), NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);                                                                                                                   
                                                                                                                                                                                                                                                                                   
                                                                                                                                                                                                                                                                                   
 return 'Success';                                                                                                                                                                                                                                                                 
 END;                                                                                                                                                                                                                                                                              
 $function$                                                                                                                                                                                                                                                                        

